-- =====================================================================
-- RetailMart V3 — converted for the RetailMart SQL Analytics project
-- (PostgreSQL 13+)
--
-- Same data as retailmart_v3.sql, reshaped to the table/column names the
-- KPI queries in 02_kpi_queries/ use. See convert_v3_to_kpi_layout.sql
-- for exactly what was renamed/added. No V3 data was removed.
--
-- Main changes:
--   core.dim_date      date_key is now the DATE (old int key -> date_id);
--                      day_name 'Mon'..'Sun', month_name 'Jan'..'Dec'
--   products.products  product_id -> prod_id, product_name -> prod_name,
--                      + category, brand (from dim_brand / dim_category)
--   products.inventory product_id -> prod_id, quantity_on_hand -> stock_qty
--   stores.stores      + region (from dim_region)
--   stores.employees   employee_id -> emp_id
--   stores.departments new (copy of core.dim_department)
--   customers.customers customer_id -> cust_id, + full_name, city, state
--                      (default address), join_date, gender*, age*
--   customers.reviews  customer_id -> cust_id, product_id -> prod_id
--   customers.loyalty_points  new (from loyalty.members)
--   sales.orders       + total_amount (= net_total)
--   sales.order_items  + discount (percent, = discount_amount / gross * 100)
--
--   * gender and age don't exist in V3. They are GENERATED practice values
--     (same every load), not real data.
--
-- Load:  createdb retailmart
--        psql -d retailmart -f retailmart_v3_kpi.sql
-- Safe to re-run: each schema is dropped and recreated.
-- =====================================================================
DROP SCHEMA IF EXISTS core CASCADE;
DROP SCHEMA IF EXISTS products CASCADE;
DROP SCHEMA IF EXISTS stores CASCADE;
DROP SCHEMA IF EXISTS customers CASCADE;
DROP SCHEMA IF EXISTS sales CASCADE;
DROP SCHEMA IF EXISTS finance CASCADE;
DROP SCHEMA IF EXISTS hr CASCADE;
DROP SCHEMA IF EXISTS marketing CASCADE;
DROP SCHEMA IF EXISTS support CASCADE;
DROP SCHEMA IF EXISTS web_events CASCADE;
DROP SCHEMA IF EXISTS supply_chain CASCADE;
DROP SCHEMA IF EXISTS loyalty CASCADE;
DROP SCHEMA IF EXISTS manufacture CASCADE;
DROP SCHEMA IF EXISTS payroll CASCADE;
DROP SCHEMA IF EXISTS call_center CASCADE;
DROP SCHEMA IF EXISTS audit CASCADE;

--
-- PostgreSQL database dump
--



SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'SQL_ASCII';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

