--
-- Name: v_orders_with_customer; Type: VIEW; Schema: sales; Owner: -
--

CREATE VIEW sales.v_orders_with_customer AS
 SELECT o.order_id,
    o.cust_id,
    o.store_id,
    o.order_date,
    o.order_status,
    o.gross_total,
    o.discount_amount,
    o.net_total,
    o.payment_mode_id,
    c.first_name,
    c.last_name
   FROM (sales.orders o
     JOIN customers.customers c ON ((o.cust_id = c.cust_id)));


