CREATE TABLE support.tickets (
    ticket_id integer NOT NULL,
    customer_id integer NOT NULL,
    agent_id integer,
    category character varying(30) NOT NULL,
    priority character varying(10) NOT NULL,
    status character varying(15) NOT NULL,
    created_date timestamp without time zone NOT NULL,
    resolved_date timestamp without time zone,
    subject character varying(150) NOT NULL
);


--
-- Name: events; Type: TABLE; Schema: web_events; Owner: -
--

CREATE TABLE web_events.events (
    event_id integer NOT NULL,
    session_id character varying(20) NOT NULL,
    customer_id integer,
    event_type character varying(20) NOT NULL,
    item_id integer,
    event_timestamp timestamp without time zone NOT NULL
);


--
-- Name: page_views; Type: TABLE; Schema: web_events; Owner: -
--

CREATE TABLE web_events.page_views (
    view_id integer NOT NULL,
    session_id character varying(20) NOT NULL,
    customer_id integer,
    page_url character varying(150) NOT NULL,
    device_type character varying(15) NOT NULL,
    view_timestamp timestamp without time zone NOT NULL,
    referrer character varying(30)
);


